use std :: path :: { Path , PathBuf } ; use std :: sync :: Arc ; use anyhow :: Context ; use forge_app :: domain :: Skill ; use forge_app :: { EnvironmentInfra , FileInfoInfra , FileReaderInfra , Walker , WalkerInfra } ; use forge_domain :: SkillRepository ; use futures :: future :: join_all ; use gray_matter :: Matter ; use gray_matter :: engine :: YAML ; use serde :: Deserialize ; use forge_config :: ForgeConfig ; use forge_infra :: ForgeInfra ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Resolves skill conflicts by keeping the last occurrence of each skill name"] # [doc = ""] # [doc = " This gives precedence to later sources (CWD > Global)"] fn resolve_skill_conflicts (skills : Vec < Skill >) -> Vec < Skill > { let mut seen = std :: collections :: HashMap :: new () ; let mut result = Vec :: new () ; for skill in skills { if let Some (idx) = seen . get (& skill . name) { if let Some (existing) = result . get_mut (* idx) { * existing = skill . clone () ; } } else { seen . insert (skill . name . clone () , result . len ()) ; result . push (skill) ; } } result }